[K-Doctor 전문과목 신장내과 v0.1 적용]

[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-nephrology",
  "answer": "거품뇨 + 양측 다리 부종 조합은 신증후군 범주(사구체 질환)를 우선 배제 대상으로 두고, 동시에 심부전·간경변·정맥 질환·약물성 부종 같은 비신장 원인도 배제 근거 없이 제거하지 않습니다. 확정은 소변 단백 정량(24시간 요단백 또는 소변 단백/크레아티닌 비)과 혈액 신기능·알부민·전해질·지질, 소변 검사(현미경 포함)로 하며, 필요 시 신장 초음파·신장 조직 검사 의뢰로 좁힙니다. 다만 입력에 경과·기저질환·복용약·전신 증상이 없어 신증후군과 급성 신손상, 만성 신질환 급성 악화를 구분할 수 없습니다.",
  "red_flag": {
    "present": false,
    "items": []
  },
  "hypotheses": [
    {
      "name": "신증후군 범주(사구체 질환 — 미세변화·국소분절사구체경화·막성신증 등)",
      "icd10": "",
      "must_not_miss": true,
      "probability_band": "high",
      "supports": [
        { "text": "환자가 표현한 거품뇨(단백뇨 시사 소견)", "basis": "history" },
        { "text": "양측 다리 부종(저알부민혈증·체액 저류와 부합)", "basis": "history" }
      ],
      "against": [
        { "text": "혈압·체중 변화·소변량 변화·알부민·단백 정량 등 확인된 값이 없음", "basis": "history" },
        { "text": "혈뇨·고혈압·전신 증상(발열·관절통·발진) 미확인", "basis": "history" }
      ]
    },
    {
      "name": "급성 신손상(신전성/신성/신후성)",
      "icd10": "",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "부종(체액 저류) — 신기능 저하 시 동반 가능", "basis": "history" }
      ],
      "against": [
        { "text": "소변량 감소·무뇨 여부 미확인", "basis": "history" },
        { "text": "크레아티닌·전해질·소변 검사값 없음", "basis": "history" }
      ]
    },
    {
      "name": "만성 신질환의 급성 악화 / 요독증",
      "icd10": "",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "부종", "basis": "history" }
      ],
      "against": [
        { "text": "기저 신장 질환·당뇨·고혈압 병력 미확인", "basis": "history" },
        { "text": "구토·가려움·심한 무기력·호흡곤란 등 요독 증상 미확인", "basis": "history" },
        { "text": "이전 신기능 검사값 없음", "basis": "history" }
      ]
    },
    {
      "name": "비신장성 부종 — 심부전·간경변·정맥 부전·약물성·갑상선",
      "icd10": "",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "양측 다리 부종", "basis": "history" }
      ],
      "against": [
        { "text": "호흡곤란·야간 기좌호흡·복수·간질환 병력 미확인", "basis": "history" },
        { "text": "NSAIDs·칼슘차단제·스테로이드 등 부종 유발 약물 복용 이력 미확인", "basis": "history" }
      ]
    }
  ],
  "missing_info": [
    "부종이 처음 생긴 시점과 진행 속도(수일 급성 vs 수주~수개월 만성), 그리고 같은 기간 소변량·체중 변화가 있었는지 — 이 하나가 신증후군(만성·서서히)·급성 신손상(급성) 구분 판별력이 가장 큽니다."
  ],
  "suggested_tests": [
    { "name": "소변 검사(딥스틱 + 현미경)", "purpose": "단백뇨·혈뇨·원주 확인", "urgency": "now", "basis": "guideline" },
    { "name": "소변 단백 정량(24시간 요단백 또는 소변 단백/크레아티닌 비)", "purpose": "신증후군 범위 단백뇨 확인", "urgency": "now", "basis": "guideline" },
    { "name": "혈액 검사 — 크레아티닌·전해질(나트륨·칼륨)·알부민·총단백·지질·혈당", "purpose": "신기능·저알부민혈증·전해질 이상 확인", "urgency": "now", "basis": "guideline" },
    { "name": "신장 초음파", "purpose": "신장 크기·피질 두께·수신증·폐색·결석·낭종 확인", "urgency": "24h", "basis": "guideline" },
    { "name": "혈압 자가 측정 기록(가정 혈압, 측정 조건 기록)", "purpose": "신혈관성·사구체 질환 관련 고혈압 확인", "urgency": "routine", "basis": "history" },
    { "name": "신장 조직 검사 의뢰", "purpose": "사구체 질환 아형 확정(신증후군·급진성 사구체신염 의심 시)", "urgency": "routine", "basis": "guideline" }
  ],
  "suggested_treatments": [
    { "kind": "self_care", "description": "염분·수분 섭취와 단백질 섭취 수준은 담당 의사와 상의. NSAIDs·한약·민간요법·건강기능식품 등 신독성 가능 물질 회피. 가정 혈압과 체중을 매일 같은 조건에서 기록.", "basis": "guideline" },
    { "kind": "referral", "description": "소변 단백 정량과 신기능·전해질 결과가 나오는 즉시 신장내과 평가 의뢰. 결과 확인 전까지 자가 이뇨제·수분 제한·칼륨 보충제를 임의로 시작하지 않음.", "basis": "guideline" }
  ],
  "handoff": { "better_specialty": "", "reason": "" },
  "confidence": { "clinical": 2, "information": 1 },
  "warnings": [
    "입력에 경과·기저질환·복용약·소변량·혈압·검사값이 없어 가설 정렬 근거가 제한적입니다. [규칙 C5]에 따라 confidence를 하향 표기했습니다.",
    "신기능에 따른 약물 용량 보정은 이 SP가 계산하지 않습니다(신장 규칙 5). 처방된 약물의 용량·조절은 신기능 확인 후 처방 의사·약사 확인 필요.",
    "다음 중 하나라도 확인되면 즉시 응급 회신으로 전환합니다: 소변량 급감·무뇨, 호흡곤란, 흉통, 의식 변화, 심계항진·불규칙 맥박, 근력 저하·마비, 부종의 급격한 악화, 심한 고혈압 + 두통·시야 이상."
  ]
}
[/SPECIALIST_FINDING]

자기 점검: C1 — 위험 신호(NE1~NE9, R계열) 미확인, RED_FLAG 없음으로 표기(단, warnings에 전환 조건 명시). C2 — 모든 항목에 근거 유형 부착. C3 — "확정 진단" 표현 사용 안 함("확정"은 검사로 판정한다는 절차 서술, 단정 아님). C4 — 용량 서술 없음, dose 키 생략.
